package main

// The canonical-form vectors are generated by the reference implementation and
// checked into testdata. This test is the disagreement detector: if the two
// implementations serialize a value differently, the ids of records that
// contain it differ, and a format whose identity depends on the serializer
// cannot be implemented twice.

import (
	"encoding/json"
	"os"
	"testing"
)

type vector struct {
	Name      string `json:"name"`
	Input     string `json:"input"`
	Canonical string `json:"canonical"`
}

func loadVectors(t *testing.T) []vector {
	t.Helper()
	raw, err := os.ReadFile("testdata/canonical_vectors.json")
	if err != nil {
		t.Fatalf("read vectors: %v", err)
	}
	var vectors []vector
	if err := json.Unmarshal(raw, &vectors); err != nil {
		t.Fatalf("parse vectors: %v", err)
	}
	if len(vectors) == 0 {
		t.Fatal("no vectors")
	}
	return vectors
}

func TestCanonicalVectors(t *testing.T) {
	for _, item := range loadVectors(t) {
		value, err := decodeJSON([]byte(item.Input))
		if err != nil {
			t.Errorf("%s: decode: %v", item.Name, err)
			continue
		}
		got, err := canonicalBytes(value)
		if err != nil {
			t.Errorf("%s: canonicalize: %v", item.Name, err)
			continue
		}
		if string(got) != item.Canonical {
			t.Errorf("%s:\n got %q\nwant %q", item.Name, got, item.Canonical)
		}
	}
}

// A canonical document must be a fixed point: decoding canonical bytes and
// re-encoding them has to produce the same bytes, or C-09 is not repeatable.
func TestCanonicalIsFixedPoint(t *testing.T) {
	for _, item := range loadVectors(t) {
		value, err := decodeJSON([]byte(item.Canonical))
		if err != nil {
			t.Errorf("%s: decode canonical: %v", item.Name, err)
			continue
		}
		again, err := canonicalBytes(value)
		if err != nil {
			t.Errorf("%s: re-canonicalize: %v", item.Name, err)
			continue
		}
		if string(again) != item.Canonical {
			t.Errorf("%s: not a fixed point:\n got %q\nwant %q", item.Name, again, item.Canonical)
		}
	}
}
